NEIGHBORHOODS = [
    neighborhood(21, CITY_ID, n("Valletta", "Valletta", "La Valette", "La Valeta"), n("Pro: monumenti, ristoranti e traghetti raggiungibili a piedi. Pro: atmosfera serale dopo la partenza dei visitatori giornalieri. Contro: prezzi alti e molte scale. Contro: scelta di hotel e vita notturna più limitata rispetto a Sliema.", "Pros: monuments, restaurants and ferries are walkable. Pros: evening atmosphere after day visitors leave. Cons: high prices and many stairs. Cons: fewer hotels and less nightlife than Sliema.", "Avantages: monuments, restaurants et ferries à pied. Avantages: belle ambiance après le départ des visiteurs. Inconvénients: prix élevés et nombreux escaliers. Inconvénients: moins d'hôtels et de sorties qu'à Sliema.", "Ventajas: monumentos, restaurantes y ferris a pie. Ventajas: ambiente nocturno tras los visitantes. Desventajas: precios altos y muchas escaleras. Desventajas: menos hoteles y ocio que Sliema."), ["centrale","culturale","ristoranti"]),
    neighborhood(22, CITY_ID, n("Floriana", "Floriana", "Floriana", "Floriana"), n("Pro: accesso immediato al terminal autobus e a City Gate. Pro: più calma e verde rispetto al centro. Contro: pochi ristoranti la sera. Contro: alcune strutture sono vicine a strade trafficate.", "Pros: immediate access to the bus terminal and City Gate. Pros: quieter and greener than central Valletta. Cons: few evening restaurants. Cons: some lodging sits near busy roads.", "Avantages: accès immédiat au terminal et à City Gate. Avantages: plus calme et verte que le centre. Inconvénients: peu de restaurants le soir. Inconvénients: certains logements donnent sur des routes fréquentées.", "Ventajas: acceso inmediato a terminal y City Gate. Ventajas: más tranquila y verde que el centro. Desventajas: pocos restaurantes nocturnos. Desventajas: algunos alojamientos están junto a vías transitadas."), ["trasporti","tranquillo","verde"]),
    neighborhood(23, CITY_ID, n("Sliema", "Sliema", "Sliema", "Sliema"), n("Pro: vasta scelta di hotel, ristoranti e servizi. Pro: traghetto diretto per Valletta e lungomare. Contro: traffico e costruzioni possono essere invadenti. Contro: atmosfera meno storica e spiagge prevalentemente rocciose.", "Pros: broad choice of hotels, restaurants and services. Pros: direct ferry to Valletta and waterfront. Cons: traffic and construction can intrude. Cons: less historic atmosphere and mainly rocky swimming.", "Avantages: large choix d'hôtels, restaurants et services. Avantages: ferry direct et promenade. Inconvénients: trafic et chantiers. Inconvénients: moins historique et baignade surtout rocheuse.", "Ventajas: gran oferta de hoteles, restaurantes y servicios. Ventajas: ferri directo y paseo marítimo. Desventajas: tráfico y obras. Desventajas: menos histórica y baño sobre roca."), ["pratico","lungomare","shopping"]),
    neighborhood(24, CITY_ID, n("Three Cities", "Three Cities", "Trois Cités", "Tres Ciudades"), n("Pro: fortificazioni e porto con atmosfera più locale. Pro: collegamento rapido in traghetto con Valletta. Contro: meno frequenze e servizi in tarda serata. Contro: scale, salite e offerta ricettiva ridotta.", "Pros: fortifications and harbour with a more local feel. Pros: quick ferry to Valletta. Cons: fewer late-evening links and services. Cons: stairs, slopes and limited accommodation.", "Avantages: fortifications et port à l'ambiance locale. Avantages: ferry rapide vers La Valette. Inconvénients: moins de liaisons tardives. Inconvénients: escaliers et offre hôtelière limitée.", "Ventajas: fortificaciones y puerto con ambiente local. Ventajas: ferri rápido a La Valeta. Desventajas: menos conexiones nocturnas. Desventajas: escaleras y alojamiento limitado."), ["storico","porto","tranquillo"]),
    neighborhood(25, CITY_ID, n("St Julian's", "St Julian's", "St Julian's", "St Julian's"), n("Pro: massima concentrazione di locali e ristoranti. Pro: molti hotel e collegamenti. Contro: rumore notturno, soprattutto a Paceville. Contro: più lontano dai principali siti culturali di Valletta.", "Pros: greatest concentration of nightlife and restaurants. Pros: many hotels and connections. Cons: night noise, especially in Paceville. Cons: farther from Valletta's main cultural sights.", "Avantages: forte concentration de sorties et restaurants. Avantages: nombreux hôtels et liaisons. Inconvénients: bruit nocturne, surtout à Paceville. Inconvénients: plus loin des sites culturels.", "Ventajas: máxima concentración de ocio y restaurantes. Ventajas: muchos hoteles y conexiones. Desventajas: ruido nocturno, sobre todo Paceville. Desventajas: más lejos de los sitios culturales."), ["vita notturna","ristoranti","pratico"]),
    neighborhood(26, CITY_ID, n("Mdina e Rabat", "Mdina and Rabat", "Mdina et Rabat", "Mdina y Rabat"), n("Pro: atmosfera storica e silenziosa fuori dagli orari di punta. Pro: accesso immediato a Mdina e catacombe. Contro: dipendenza dagli autobus per Valletta e costa. Contro: scelta serale limitata e nessun porto vicino.", "Pros: historic, quiet atmosphere outside peak hours. Pros: immediate access to Mdina and catacombs. Cons: dependence on buses for Valletta and coast. Cons: limited evenings and no nearby harbour.", "Avantages: ambiance historique et calme hors pointe. Avantages: accès immédiat à Mdina et aux catacombes. Inconvénients: dépendance aux bus. Inconvénients: soirées limitées et pas de port proche.", "Ventajas: ambiente histórico y tranquilo fuera de hora punta. Ventajas: acceso inmediato a Mdina y catacumbas. Desventajas: dependencia del autobús. Desventajas: poca oferta nocturna y sin puerto cercano."), ["storico","tranquillo","culturale"]),
]
